namespace OmniCommerce.Api.Domain;

public class Cart
{
    private readonly List<CartItem> _items = [];

    private Cart() { }

    public Guid Id { get; private set; }

    // Opaque customer/session reference. Ownership is not enforced in this PoC.
    public string? OwnerReference { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }
    public DateTimeOffset UpdatedAt { get; private set; }
    public DateTimeOffset? ExpiresAt { get; private set; }

    // Generated by SQL Server; the source of the strong ETag.
    public byte[] RowVersion { get; private set; } = [];

    public IReadOnlyCollection<CartItem> Items => _items;

    public static Cart Create(DateTimeOffset now, string? ownerReference = null, DateTimeOffset? expiresAt = null) =>
        new()
        {
            Id = Guid.NewGuid(),
            OwnerReference = ownerReference,
            CreatedAt = now,
            UpdatedAt = now,
            ExpiresAt = expiresAt,
        };

    public CartItem AddItem(Guid productId, int quantity, DateTimeOffset now)
    {
        EnsurePositive(quantity);

        var item = _items.FirstOrDefault(i => i.ProductId == productId);
        if (item is null)
        {
            item = new CartItem(Guid.NewGuid(), Id, productId, quantity);
            _items.Add(item);
        }
        else
        {
            item.Quantity += quantity;
        }

        UpdatedAt = now;
        return item;
    }

    public bool SetItemQuantity(Guid productId, int quantity, DateTimeOffset now)
    {
        EnsurePositive(quantity);

        var item = _items.FirstOrDefault(i => i.ProductId == productId);
        if (item is null)
        {
            return false;
        }

        item.Quantity = quantity;
        UpdatedAt = now;
        return true;
    }

    public bool RemoveItem(Guid productId, DateTimeOffset now)
    {
        var item = _items.FirstOrDefault(i => i.ProductId == productId);
        if (item is null)
        {
            return false;
        }

        _items.Remove(item);
        UpdatedAt = now;
        return true;
    }

    internal static int EnsurePositive(int quantity) =>
        quantity > 0
            ? quantity
            : throw new ArgumentOutOfRangeException(nameof(quantity), quantity, "Quantity must be positive.");
}
